package com.jadhavr.erp.email.worker;
import com.jadhavr.erp.email.entity.EmailNotification;import com.jadhavr.erp.email.enums.EmailStatus;import com.jadhavr.erp.email.repository.EmailNotificationRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.List;
@Service public class EmailClaimService{private final EmailNotificationRepository repo;public EmailClaimService(EmailNotificationRepository r){repo=r;}@Transactional public List<EmailNotification>claim(int limit){List<EmailNotification>x=repo.lockEligible(limit);x.forEach(n->{n.setStatus(EmailStatus.PROCESSING);n.setProcessingStartedAt(LocalDateTime.now());});return repo.saveAll(x);}@Transactional public void recoverStale(){List<EmailNotification>x=repo.findByStatusAndProcessingStartedAtBefore(EmailStatus.PROCESSING,LocalDateTime.now().minusMinutes(10));x.forEach(n->{n.setStatus(EmailStatus.RETRY_PENDING);n.setNextRetryAt(LocalDateTime.now());n.setFailureReason("Recovered after interrupted processing");});repo.saveAll(x);}}
